import React from 'react';
import { useParams } from 'react-router-dom';

const Archiving: React.FC = () => {
  const { category } = useParams<{ category: string }>();

  // Mock data for display
  const works = Array.from({ length: 9 }).map((_, i) => ({
    id: i,
    title: `Project ${i + 1}`,
    tags: ['3D', 'AI', 'Render'],
    imageUrl: `https://picsum.photos/seed/${category || 'all'}${i}/800/600`
  }));

  return (
    <div className="p-10 md:p-20">
      <h2 className="text-4xl font-bold mb-10 border-b border-black pb-4 capitalize">
        {category === 'all' ? 'All Works' : `${category} Archiving`}
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {works.map((work) => (
          <div key={work.id} className="group cursor-pointer">
            <div className="aspect-[4/3] overflow-hidden border border-black mb-4">
              <img 
                src={work.imageUrl} 
                alt={work.title} 
                className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500"
              />
            </div>
            <div className="flex justify-between items-start">
              <div>
                <h3 className="font-bold text-lg">{work.title}</h3>
                <p className="font-kor-thin text-sm text-neutral-600">
                  {work.tags.join(' / ')}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Archiving;

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export const sendMessageToGemini = async (prompt: string, history: { role: 'user' | 'model', text: string }[]) => {
  if (!API_KEY) {
    throw new Error("API key is not configured.");
  }

  const ai = new GoogleGenAI({ apiKey: API_KEY });

  // Custom instruction for the portfolio assistant
  const systemInstruction = `
    You are the AI Assistant for "sanniohs" (산이오스), a graphic designer specializing in 3D and AI art.
    Your tone is professional, minimalist, and artistic.
    You know that:
    - sanniohs is based in Seoul.
    - His specialty is "3D with AI Graphic Design".
    - He calls himself a "잡동사니 수집가" (collector of odds and ends).
    - Email: sanniworks@naver.com, Instagram: @sanniohs.
    Keep answers brief and helpful. Respond in the user's language (Korean or English).
  `;

  try {
    const chat = ai.chats.create({
      model: "gemini-3-flash-preview",
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    // In a real app we'd pass history to chat.sendMessage, 
    // but for simplicity and adhering to provided examples:
    const response = await chat.sendMessage({ message: prompt });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "죄송합니다. 현재 AI 비서와 연결이 원활하지 않습니다.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { sendMessageToGemini } from '../services/gemini';
import { Message } from '../types';

const ChatAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: '안녕하세요! 산이오스의 AI 비서입니다. 무엇을 도와드릴까요?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await sendMessageToGemini(userMsg, messages);
      setMessages(prev => [...prev, { role: 'model', text: response || '' }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'model', text: '오류가 발생했습니다. 다시 시도해주세요.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200]">
      {/* Trigger Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-14 h-14 bg-black text-white rounded-full flex items-center justify-center shadow-xl hover:scale-105 transition-transform"
      >
        {isOpen ? (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        ) : (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
        )}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="absolute bottom-20 right-0 w-[320px] md:w-[380px] bg-white border border-black shadow-2xl flex flex-col max-h-[500px]">
          <div className="p-4 border-b border-black font-bold uppercase tracking-widest text-xs flex justify-between items-center bg-black text-white">
            <span>AI Assistant</span>
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 min-h-[300px]">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 text-sm ${m.role === 'user' ? 'bg-neutral-100 font-kor-thin' : 'border border-black font-kor-thin bg-white'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="p-3 border border-black bg-white">
                  <div className="flex space-x-1">
                    <div className="w-1.5 h-1.5 bg-black rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-black rounded-full animate-bounce [animation-delay:-.3s]"></div>
                    <div className="w-1.5 h-1.5 bg-black rounded-full animate-bounce [animation-delay:-.5s]"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 border-t border-black flex gap-2">
            <input 
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask anything..."
              className="flex-1 text-sm focus:outline-none font-kor-thin"
            />
            <button 
              onClick={handleSend}
              className="text-xs font-bold uppercase hover:underline"
            >
              Send
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatAssistant;

