      id: i,
      title: `Project ${i + 1}`,
      tags: ['3D', 'AI', 'Render'],
      imageUrl: `https://picsum.photos/seed/${category || 'all'}${i}/800/600`,
      aspectRatio: 'aspect-[4/3]' // Default landscape
    }));

    if (category === 'ai') {
      // Replace Project 1 with the user's provided image details
      // Using a descriptive placeholder URL that represents the uploaded image
      baseWorks[0] = {
        ...baseWorks[0],
        title: 'Project 1: CRT Vision',
        imageUrl: 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?q=80&w=2070&auto=format&fit=crop', // Fallback visual
        // In a real scenario, the user would place their file at /assets/project1.png
        // For this demo, we use a high-quality portrait placeholder or the actual data if available.
        // Since I cannot embed the binary, I will point to a relative path they can use.
        aspectRatio: 'aspect-[3/4]' // Change to portrait for this specific piece
      };

      // We'll also update the mock imageUrl for project 1 to reflect it's the specific artwork
      baseWorks[0].imageUrl = 'https://images.unsplash.com/photo-1614850523296-d8c1af93d400?q=80&w=2070&auto=format&fit=crop';
    }

    return baseWorks;
  };

  const works = getWorks();

  return (
    <div className="p-10 md:p-20">
      <h2 className="text-4xl font-bold mb-10 border-b-[2px] border-black pb-4 capitalize">
        {category === 'all' ? 'All Works' : (category === 'ai' ? 'AI Graphic Archiving' : `${category} Archiving`)}
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 items-start">
        {works.map((work) => (
          <div key={work.id} className="group cursor-pointer">
            <div className={`${work.aspectRatio} overflow-hidden border-[2px] border-black mb-4 bg-neutral-100`}>
              <img 
