import React, { useState } from 'react';
import { useParams } from 'react-router-dom';

interface Work {
  id: number;
  title: string;
  imageUrl: string;
  videoUrl?: string;
  aspectRatio: string;
}

const Archiving: React.FC = () => {
  const { category } = useParams<{ category: string }>();
  const [selectedWork, setSelectedWork] = useState<Work | null>(null);

  const getWorks = (): Work[] => {
    // Generate a list of mock works
    const baseWorks = Array.from({ length: 9 }).map((_, i) => ({
      id: i,
      title: `Project ${i + 1}`,
      imageUrl: `https://picsum.photos/seed/${category || 'all'}${i}/800/600`,
      videoUrl: 'https://www.w3schools.com/html/mov_bbb.mp4', // Default sample video
      aspectRatio: 'aspect-[4/3]'
    }));

    // Specific custom logic for AI Graphics category
    if (category === 'ai') {
      baseWorks[0] = {
        id: 0,
        title: 'Project 1: CRT Vision',
        imageUrl: 'https://i.imgur.com/jA1uH5h.png',
        videoUrl: 'https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', // Another sample
        aspectRatio: 'aspect-[4/3]'
      };
    }

    return baseWorks;
  };

  const works = getWorks();

  const openVideo = (work: Work) => {
    setSelectedWork(work);
    // Disable body scroll when modal is open
    document.body.style.overflow = 'hidden';
  };

  const closeVideo = () => {
    setSelectedWork(null);
    // Restore body scroll
    document.body.style.overflow = 'auto';
  };

  return (
    <div className="p-10 md:p-20 relative">
      <h2 className="text-4xl font-bold mb-10 border-b-[2px] border-black pb-4 capitalize">
        {category === 'all' ? 'All Works' : (category === 'ai' ? 'AI Graphic Archiving' : `${category} Archiving`)}
      </h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 items-start">
        {works.map((work) => (
          <div 
            key={work.id} 
            className="group cursor-pointer"
            onClick={() => openVideo(work)}
          >
            <div className={`${work.aspectRatio} overflow-hidden border-[2px] border-black mb-4 bg-neutral-100 relative`}>
              {/* Play Icon Overlay on Hover */}
              <div className="absolute inset-0 z-10 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 bg-black/20">
                <svg className="w-16 h-16 text-white" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                </svg>
              </div>

              <img 
                src={work.imageUrl} 
                alt={work.title} 
                className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700 ease-in-out scale-100 group-hover:scale-105"
                onError={(e) => {
                  (e.target as HTMLImageElement).src = 'https://placehold.co/800x600?text=Project+Thumbnail';
                }}
              />
            </div>
            <div className="flex flex-col">
              <h3 className="font-bold text-xl tracking-tighter uppercase">{work.title}</h3>
            </div>
          </div>
        ))}
      </div>

      {/* Video Modal Overlay */}
      {selectedWork && (
        <div 
          className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/95 p-4 md:p-10 animate-in fade-in duration-300"
          onClick={closeVideo}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-white hover:text-neutral-400 transition-colors z-[1001]"
            onClick={closeVideo}
          >
            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <div 
            className="w-full max-w-5xl aspect-video bg-black relative flex flex-col"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="absolute -top-10 left-0 text-white font-bold uppercase tracking-widest text-sm">
              {selectedWork.title}
            </div>

            <video 
              src={selectedWork.videoUrl} 
              className="w-full h-full"
              controls
              autoPlay
              playsInline
            >
              Your browser does not support the video tag.
            </video>
          </div>
        </div>
      )}
    </div>
  );
};

export default Archiving;

