              </video>
            ) : (
              // Single Image Style
              <img 
                src={selectedWork.videoUrl || selectedWork.imageUrl} 
                alt={selectedWork.title}
                className="w-full h-auto max-h-[85vh] object-contain"
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
};

