    if (!url) return false;
    const cleanUrl = url.split('?')[0].split('#')[0];
    return cleanUrl.toLowerCase().endsWith('.mp4');
  };

  const nextSlide = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (selectedWork?.gallery) {
      setCurrentSlide((prev) => (prev + 1) % selectedWork.gallery!.length);
    }
  };

