                  {selectedWork.gallery.map((_, idx) => (
                    <div 
                      key={idx}
                      className={`w-1.5 h-1.5 rounded-full border border-white transition-colors cursor-pointer ${idx === currentSlide ? 'bg-white' : 'bg-transparent opacity-50'}`}
